namespace sv_982ba029eb7f479b81e186aa319390b5.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

using System.ComponentModel.DataAnnotations;

namespace sv_982ba029eb7f479b81e186aa319390b5.Models;

public class PersonalInfoModel
{
    [Required(ErrorMessage = "Full name is required.")]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
    public string Email { get; set; } = "";

    [Required(ErrorMessage = "Phone number is required.")]
    public string Phone { get; set; } = "";

    [Required(ErrorMessage = "Address is required.")]
    public string Address { get; set; } = "";
}

public class WorkEntryModel
{
    [Required(ErrorMessage = "Company name is required.")]
    public string Company { get; set; } = "";

    [Required(ErrorMessage = "Job title is required.")]
    public string Title { get; set; } = "";

    public DateTime? StartDate { get; set; }

    public DateTime? EndDate { get; set; }

    public bool IsCurrent { get; set; }

    public string Description { get; set; } = "";
}

public class ReferenceModel
{
    [Required(ErrorMessage = "Name is required.")]
    public string Name { get; set; } = "";

    [Required(ErrorMessage = "Relationship is required.")]
    public string Relationship { get; set; } = "";

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
    public string Email { get; set; } = "";

    [Required(ErrorMessage = "Phone number is required.")]
    public string Phone { get; set; } = "";
}

@namespace sv_982ba029eb7f479b81e186aa319390b5.Components.JobApplication

<nav aria-label="Application steps" class="step-indicator mb-4">
    <ol class="d-flex list-unstyled justify-content-between m-0 p-0">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var isActive = step == CurrentStep;
            var isCompleted = CompletedSteps.Contains(step);
            var isFuture = !isActive && !isCompleted;

            <li class="step-item @(isActive ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")"
                @onclick="() => HandleStepClick(step)"
                role="@(isCompleted ? "button" : "listitem")"
                tabindex="@(isCompleted ? 0 : -1)">
                <div class="step-circle">
                    @if (isCompleted)
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </div>
                <div class="step-label">@StepNames[i]</div>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames =
    [
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    ];

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task HandleStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

.step-indicator ol {
    counter-reset: step;
}

.step-item {
    flex: 1;
    text-align: center;
    position: relative;
}

.step-item:not(:last-child)::after {
    content: '';
    position: absolute;
    top: 18px;
    left: calc(50% + 22px);
    width: calc(100% - 44px);
    height: 2px;
    background-color: #dee2e6;
}

.step-item.completed:not(:last-child)::after {
    background-color: #198754;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    margin-bottom: 0.25rem;
    position: relative;
    z-index: 1;
    transition: background-color 0.2s, color 0.2s;
}

.step-item.active .step-circle {
    background-color: #0d6efd;
    color: white;
}

.step-item.completed .step-circle {
    background-color: #198754;
    color: white;
    cursor: pointer;
}

.step-item.completed .step-circle:hover {
    background-color: #157347;
}

.step-item.future .step-circle {
    background-color: #dee2e6;
    color: #6c757d;
}

.step-label {
    font-size: 0.78rem;
    color: #6c757d;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
    cursor: pointer;
}

