toolArgs.file_text:
.step-indicator ol {
    counter-reset: step;
}

.step-item {
    flex: 1;
    text-align: center;
    position: relative;
}

.step-item:not(:last-child)::after {
    content: '';
    position: absolute;
    top: 18px;
    left: calc(50% + 22px);
    width: calc(100% - 44px);
    height: 2px;
    background-color: #dee2e6;
}

.step-item.completed:not(:last-child)::after {
    background-color: #198754;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    margin-bottom: 0.25rem;
    position: relative;
    z-index: 1;
    transition: background-color 0.2s, color 0.2s;
}

.step-item.active .step-circle {
    background-color: #0d6efd;
    color: white;
}

.step-item.completed .step-circle {
    background-color: #198754;
    color: white;
    cursor: pointer;
}

.step-item.completed .step-circle:hover {
    background-color: #157347;
}

.step-item.future .step-circle {
    background-color: #dee2e6;
    color: #6c757d;
}

.step-label {
    font-size: 0.78rem;
    color: #6c757d;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
    cursor: pointer;
}

