            <h6 class="card-title mb-0">Reference @(Index + 1)</h6>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row">
            <div class="col-md-6 mb-3">
                <label class="form-label">Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="Reference.Name" @bind:event="oninput" />
            </div>
            <div class="col-md-6 mb-3">
                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="Reference.Relationship" @bind:event="oninput" />
            </div>
        </div>
        <div class="row">
            <div class="col-md-6 mb-3">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="Reference.Email" @bind:event="oninput" />
            </div>
            <div class="col-md-6 mb-0">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="Reference.Phone" @bind:event="oninput" />
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

@namespace sv_982ba029eb7f479b81e186aa319390b5.Components.JobApplication
@using sv_982ba029eb7f479b81e186aa319390b5.Models

<EditForm Model="Model" OnValidSubmit="HandleValidSubmit">
    <DataAnnotationsValidator />

    @if (!string.IsNullOrEmpty(EmailError))
    {
        <div class="alert alert-danger py-2">@EmailError</div>
    }

    <div class="mb-3">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <InputText @bind-Value="Model.FullName" class="form-control" placeholder="Jane Doe" />
        <ValidationMessage For="() => Model.FullName" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email <span class="text-danger">*</span></label>
        <InputText @bind-Value="Model.Email" class="form-control" placeholder="jane@example.com" />
        <ValidationMessage For="() => Model.Email" />
    </div>

    <div class="mb-3">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <InputText @bind-Value="Model.Phone" class="form-control" placeholder="(555) 123-4567" />
        <ValidationMessage For="() => Model.Phone" />
    </div>

    <div class="mb-3">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <InputText @bind-Value="Model.Address" class="form-control" placeholder="123 Main St, City, State" />
        <ValidationMessage For="() => Model.Address" />
    </div>

    <div class="d-flex justify-content-end">
        <button type="submit" class="btn btn-primary" disabled="@IsValidating">
            @if (IsValidating)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Next
        </button>
    </div>
</EditForm>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public string? EmailError { get; set; }
    [Parameter] public bool IsValidating { get; set; }

    private async Task HandleValidSubmit()
    {
        await OnNext.InvokeAsync();
    }
