@namespace sv_982ba029eb7f479b81e186aa319390b5.Components.JobApplication
@using sv_982ba029eb7f479b81e186aa319390b5.Models

@if (SubmittedId.HasValue)
{
    <div class="text-center py-5">
        <div class="mb-3">
            <span class="d-inline-flex align-items-center justify-content-center bg-success text-white rounded-circle"
                  style="width:64px;height:64px;font-size:2rem;">✓</span>
        </div>
        <h3 class="text-success">Application Submitted!</h3>
        <p class="lead">Your application ID is <strong>#@SubmittedId</strong></p>
        <p class="text-muted">We'll review your application and get back to you soon.</p>
    </div>
}
else
{
    <h5 class="mb-4">Review Your Application</h5>

    @if (!string.IsNullOrEmpty(SubmitError))
    {
        <div class="alert alert-danger py-2">@SubmitError</div>
    }

    <!-- Personal Information -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Personal Information</strong>
            <a href="" @onclick:preventDefault @onclick="() => OnEditSection.InvokeAsync(1)" class="text-decoration-none">Edit</a>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-3">Name</dt>
                <dd class="col-sm-9">@Personal.FullName</dd>
                <dt class="col-sm-3">Email</dt>
                <dd class="col-sm-9">@Personal.Email</dd>
                <dt class="col-sm-3">Phone</dt>
                <dd class="col-sm-9">@Personal.Phone</dd>
                <dt class="col-sm-3">Address</dt>
                <dd class="col-sm-9">@Personal.Address</dd>
            </dl>
        </div>
    </div>

    <!-- Work History -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Work History</strong>
            <a href="" @onclick:preventDefault @onclick="() => OnEditSection.InvokeAsync(2)" class="text-decoration-none">Edit</a>
        </div>
        <div class="card-body">
            @foreach (var entry in WorkEntries)
            {
                <div class="mb-3 pb-3 border-bottom last-no-border">
                    <h6 class="mb-1">@entry.Title at @entry.Company</h6>
                    <p class="text-muted small mb-1">
                        @entry.StartDate?.ToString("MMM yyyy") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </p>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="mb-0 small">@entry.Description</p>
                    }
                </div>
            }
        </div>
    </div>

    <!-- References -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>References</strong>
            <a href="" @onclick:preventDefault @onclick="() => OnEditSection.InvokeAsync(3)" class="text-decoration-none">Edit</a>
        </div>
        <div class="card-body">
            @foreach (var r in References)
            {
                <div class="mb-2 pb-2 border-bottom last-no-border">
                    <strong>@r.Name</strong> <span class="text-muted">(@r.Relationship)</span><br />
                    <small>@r.Email · @r.Phone</small>
                </div>
            }
        </div>
    </div>

    <!-- Cover Letter -->
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Cover Letter</strong>
            <a href="" @onclick:preventDefault @onclick="() => OnEditSection.InvokeAsync(4)" class="text-decoration-none">Edit</a>
        </div>
        <div class="card-body">
            @if (!string.IsNullOrWhiteSpace(CoverLetter))
            {
                <p class="mb-0" style="white-space: pre-wrap;">@CoverLetter</p>
            }
            else
            {
                <p class="text-muted mb-0 fst-italic">No cover letter provided.</p>
            }
        </div>
    </div>

    <div class="d-flex justify-content-between">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-success btn-lg" @onclick="OnSubmit" disabled="@IsSubmitting">
            @if (IsSubmitting)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Submit Application
        </button>
    </div>
}

