    [Parameter] public EventCallback OnBack { get; set; }

    private List<string> validationErrors = [];

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        validationErrors.Clear();

        for (int i = 0; i < Entries.Count; i++)
        {
            var entry = Entries[i];
            var pos = i + 1;

            if (string.IsNullOrWhiteSpace(entry.Company))
                validationErrors.Add($"Position {pos}: Company name is required.");
            if (string.IsNullOrWhiteSpace(entry.Title))
                validationErrors.Add($"Position {pos}: Job title is required.");
            if (entry.StartDate is null)
                validationErrors.Add($"Position {pos}: Start date is required.");
        }

        if (validationErrors.Count == 0)
            await OnNext.InvokeAsync();
    }
}
