}

@namespace sv_982ba029eb7f479b81e186aa319390b5.Components.JobApplication
@using sv_982ba029eb7f479b81e186aa319390b5.Models

<EditForm Model="Model" OnValidSubmit="HandleValidSubmit">
    <DataAnnotationsValidator />

    @if (!string.IsNullOrEmpty(EmailError))
    {
        <div class="alert alert-danger py-2">@EmailError</div>
    }

    <div class="mb-3">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <InputText @bind-Value="Model.FullName" class="form-control" placeholder="Jane Doe" />
        <ValidationMessage For="() => Model.FullName" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email <span class="text-danger">*</span></label>
        <InputText @bind-Value="Model.Email" class="form-control" placeholder="jane@example.com" />
        <ValidationMessage For="() => Model.Email" />
    </div>

    <div class="mb-3">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <InputText @bind-Value="Model.Phone" class="form-control" placeholder="(555) 123-4567" />
        <ValidationMessage For="() => Model.Phone" />
    </div>

    <div class="mb-3">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <InputText @bind-Value="Model.Address" class="form-control" placeholder="123 Main St, City, State" />
        <ValidationMessage For="() => Model.Address" />
    </div>

    <div class="d-flex justify-content-end">
        <button type="submit" class="btn btn-primary" disabled="@IsValidating">
            @if (IsValidating)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Next
        </button>
    </div>
</EditForm>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public string? EmailError { get; set; }
    [Parameter] public bool IsValidating { get; set; }

    private async Task HandleValidSubmit()
    {
        await OnNext.InvokeAsync();
    }
}

@namespace sv_982ba029eb7f479b81e186aa319390b5.Components.JobApplication
@using sv_982ba029eb7f479b81e186aa319390b5.Models

<h5 class="mb-3">References</h5>
<p class="text-muted small">Please provide 2–3 professional references.</p>

@if (validationErrors.Count > 0)
{
    <div class="alert alert-danger py-2">
        <ul class="mb-0 ps-3">
            @foreach (var error in validationErrors)
            {
                <li>@error</li>
            }
        </ul>
    </div>
}

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    <ReferenceForm Reference="References[index]"
                   Index="index"
                   CanRemove="References.Count > 2"
                   OnRemove="() => RemoveReference(index)" />
}

@if (References.Count < 3)
{
    <button type="button" class="btn btn-outline-secondary mb-4" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between">
    <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<string> validationErrors = [];

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        validationErrors.Clear();

        for (int i = 0; i < References.Count; i++)
        {
            var r = References[i];
            var num = i + 1;

            if (string.IsNullOrWhiteSpace(r.Name))
                validationErrors.Add($"Reference {num}: Name is required.");
            if (string.IsNullOrWhiteSpace(r.Relationship))
                validationErrors.Add($"Reference {num}: Relationship is required.");
            if (string.IsNullOrWhiteSpace(r.Email))
                validationErrors.Add($"Reference {num}: Email is required.");
            if (string.IsNullOrWhiteSpace(r.Phone))
                validationErrors.Add($"Reference {num}: Phone is required.");
        }

        if (validationErrors.Count == 0)
            await OnNext.InvokeAsync();
    }
}

