@using sv_982ba029eb7f479b81e186aa319390b5.Components.JobApplication
@using sv_982ba029eb7f479b81e186aa319390b5.Models

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnStepClicked="GoToStep" />

    <div class="mt-4">
        @switch (currentStep)
        {
            case 1:
                <PersonalInfoStep Model="personalInfo"
                                  EmailError="@emailError"
                                  IsValidating="isValidatingEmail"
                                  OnNext="HandlePersonalInfoNext" />
                break;

            case 2:
                <WorkHistoryStep Entries="workEntries"
                                 OnNext="() => AdvanceStep()"
                                 OnBack="() => GoToStep(currentStep - 1)" />
                break;

            case 3:
                <ReferencesStep References="references"
                                OnNext="() => AdvanceStep()"
                                OnBack="() => GoToStep(currentStep - 1)" />
                break;

            case 4:
                <CoverLetterStep CoverLetter="@coverLetter"
                                 OnCoverLetterChanged="val => coverLetter = val"
                                 OnNext="() => AdvanceStep()"
                                 OnBack="() => GoToStep(currentStep - 1)" />
                break;

            case 5:
                <ReviewStep Personal="personalInfo"
                            WorkEntries="workEntries"
                            References="references"
                            CoverLetter="@coverLetter"
                            SubmittedId="submittedId"
                            IsSubmitting="isSubmitting"
                            SubmitError="@submitError"
                            OnEditSection="GoToStep"
                            OnSubmit="HandleSubmit"
                            OnBack="() => GoToStep(currentStep - 1)" />
                break;
        }
    </div>
</div>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private int currentStep = 1;
    private HashSet<int> completedSteps = [];

    // Form state
    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    // UI state
    private string? emailError;
    private bool isValidatingEmail;
    private bool isSubmitting;
    private string? submitError;
    private int? submittedId;

    private async Task HandlePersonalInfoNext()
    {
        emailError = null;
        isValidatingEmail = true;

        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(personalInfo.Email);
            if (!isValid)
            {
                emailError = "This email address could not be verified. Please use a different email.";
                return;
            }

            AdvanceStep();
        }
        catch
        {
            emailError = "Unable to validate email at this time. Please try again.";
        }
        finally
        {
            isValidatingEmail = false;
        }
    }

    private void AdvanceStep()
    {
        completedSteps.Add(currentStep);
        if (currentStep < 5)
            currentStep++;
    }

    private void GoToStep(int step)
    {
        if (step >= 1 && step <= 5)
            currentStep = step;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
                new WorkHistory(workEntries.Select(e => new WorkEntry(
                    e.Company,
                    e.Title,
                    e.StartDate ?? DateTime.MinValue,
                    e.IsCurrent ? null : e.EndDate,
                    e.Description
                )).ToList()),
                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );

            submittedId = await ApplicationService.SubmitApplicationAsync(application);
            completedSteps.Add(5);
        }
        catch
        {
            submitError = "Something went wrong while submitting your application. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

