+    private string? emailError;
+    private bool isValidatingEmail;
+    private bool isSubmitting;
+    private string? submitError;
+    private int? submittedId;
+
+    private async Task HandlePersonalInfoNext()
+    {
+        emailError = null;
+        isValidatingEmail = true;
+
+        try
+        {
+            var isValid = await ApplicationService.ValidateEmailAsync(personalInfo.Email);
+            if (!isValid)
+            {
+                emailError = "This email address could not be verified. Please use a different email.";
+                return;
+            }
+
+            AdvanceStep();
+        }
+        catch
+        {
+            emailError = "Unable to validate email at this time. Please try again.";
+        }
+        finally
+        {
+            isValidatingEmail = false;
+        }
+    }
+
+    private void AdvanceStep()
+    {
+        completedSteps.Add(currentStep);
+        if (currentStep < 5)
+            currentStep++;
+    }
+
+    private void GoToStep(int step)
+    {
+        if (step >= 1 && step <= 5)
+            currentStep = step;
+    }
+
+    private async Task HandleSubmit()
+    {
+        isSubmitting = true;
+        submitError = null;
+
+        try
+        {
+            var application = new JobApplication(
+                new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
+                new WorkHistory(workEntries.Select(e => new WorkEntry(
+                    e.Company,
+                    e.Title,
+                    e.StartDate ?? DateTime.MinValue,
+                    e.IsCurrent ? null : e.EndDate,
+                    e.Description
+                )).ToList()),
+                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
+                coverLetter
+            );
+
+            submittedId = await ApplicationService.SubmitApplicationAsync(application);
+            completedSteps.Add(5);
+        }
+        catch
+        {
+            submitError = "Something went wrong while submitting your application. Please try again.";
+        }
+        finally
+        {
+            isSubmitting = false;
+        }
+    }
+}
